    @Test
    void testRedisLock(){
        SimpleRedisLock test = new SimpleRedisLock("test", stringRedisTemplate);
        boolean tryLock = test.tryLock(1000);
        if (tryLock){
            try {
                System.out.println("获取锁成功");
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
        try {
            Thread.sleep(10000L);
            test.unlock();
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    }

